// Pre-procesador de fechas — TFO TOFO Pizza (CDMX)
// Adaptado del patrón Napier; cambia solo el TZ.
const TZ = 'America/Mexico_City';
const now = new Date(new Date().toLocaleString('en-US', { timeZone: TZ }));
const pad = n => String(n).padStart(2, '0');
const toISO = d => `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const dnames = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];

const ctx = {
  hoy: toISO(now),
  manana: toISO(new Date(now.getFullYear(), now.getMonth(), now.getDate()+1)),
  pasado_manana: toISO(new Date(now.getFullYear(), now.getMonth(), now.getDate()+2)),
  dia_semana_hoy: dnames[now.getDay()],
  hora_actual: `${pad(now.getHours())}:${pad(now.getMinutes())}`,
  proximos_7_dias: {}
};

for (let i = 1; i <= 7; i++) {
  const dd = new Date(now.getFullYear(), now.getMonth(), now.getDate() + i);
  const nn = dnames[dd.getDay()];
  if (!ctx.proximos_7_dias[nn]) ctx.proximos_7_dias[nn] = toISO(dd);
}

return [{ json: { ...$input.first().json, fecha_contexto: ctx } }];

try {
  const body = $input.first().json.body;

  let canal = 'Desconocido';

  if (body?.tt_username) {
    canal = 'TikTok';
  } else if (body?.whatsapp_phone) {
    canal = 'WhatsApp';
  } else if (body?.ig_id) {
    canal = 'Instagram';
  } else if (body?.fb_id) {
    canal = 'Facebook';
  }

  return [{ json: { canal } }];

} catch (error) {
  return [{ json: { canal: 'Error', detalle: error.message } }];
}

// Obtenemos el valor de 'respuesta_definitiva' desde el input
const respuestaDefinitiva = $('Webhook').first().json.body.custom_fields.respuesta_definitiva || '';

// Función para separar el texto y detectar múltiples tipos de enlaces (audio, imágenes, video, otros)
function separarMensaje(texto) {
  if (!texto) {
    return { texto: '', audio: [], imagenes: [], videos: [], links: [] };
  }

  // 1) Detectar TODAS las URLs (cualquier dominio)
  const urlRegex = /https?:\/\/[^\s,]+/g;
  const urls = texto.match(urlRegex) || [];

  // 2) Clasificar por extensión (ignorando querystrings)
  const audios = [];
  const imagenes = [];
  const videos = [];
  const otros = [];

  const isExt = (url, exts) => {
    const base = url.split('?')[0].toLowerCase();
    return new RegExp(`\\.(${exts.join('|')})$`, 'i').test(base);
  };

  for (const url of urls) {
    if (isExt(url, ['mp3','m4a','wav','ogg','aac','flac','webm'])) {
      audios.push(url);
    } else if (isExt(url, ['jpg','jpeg','png','gif','webp','bmp','svg'])) {
      imagenes.push(url);
    } else if (isExt(url, ['mp4','mov','mkv','avi','webm'])) {
      videos.push(url);
    } else {
      // Si querés, acá podés intentar heurísticas por path (ej. "/voice/" o "/image/")
      otros.push(url);
    }
  }

  // 3) Limpiar el texto (remover URLs y comas sobrantes, y compactar espacios)
  const textoLimpio = texto
    .replace(urlRegex, '')    // quitamos URLs
    .replace(/,/g, '')        // quitamos comas
    .replace(/\s{2,}/g, ' ')  // espacios múltiples -> uno
    .trim();

  return {
    texto: textoLimpio,
    audio: audios,       // compatibilidad con tu estructura actual
    imagenes,
    videos,
    links: otros
  };
}

// Llamamos a la función y devolvemos el resultado
return separarMensaje(respuestaDefinitiva);

function generarCodigo() {
  const letras = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const numeros = '0123456789';
  let code = '';

  // 3 letras mayúsculas
  for (let i = 0; i < 3; i++) {
    code += letras.charAt(Math.floor(Math.random() * letras.length));
  }
  // 5 dígitos
  for (let i = 0; i < 5; i++) {
    code += numeros.charAt(Math.floor(Math.random() * numeros.length));
  }
  return code;
}

const hoy = new Date();
const expiracion = new Date(hoy.getTime() + (3 * 24 * 60 * 60 * 1000));
const expiracionFormateada = expiracion.toISOString().split('T')[0];

return JSON.stringify({
  code: generarCodigo(),
  valid_until: expiracionFormateada
});

